import React, {type ReactNode} from 'react';
import Translate, {translate} from '@docusaurus/Translate';
import {
  LandingLayout,
  Hero,
  Section,
  FeatureGrid,
  FAQ,
  CTABand,
  TradingViewWidget,
  type Feature,
} from '@site/src/components/landing';
import {
  FaqJsonLd,
  BreadcrumbsJsonLd,
  type FaqJsonLdItem,
} from '@site/src/components/seo';
import GlassCard from '@site/src/components/GlassCard';
import type {Cryptocurrency} from '../types';
import shared from '../styles.module.css';

/*
 * Per-coin trading bot page — programmatic route /<slug>-trading-bot.
 *
 * Generated by the octobot-programmatic-pages plugin, gated on `crypto.whatIs`
 * so it only emits for documented coins (same gate as the what-is-<slug>
 * page). The page is anchored on per-coin content — the `whatIs` prose, the
 * coin's own FAQ entries and a live chart — with a generic strategy grid as
 * the shared part. The plugin skips any coin whose slug collides with an
 * exchange slug, since exchanges own the same /<slug>-trading-bot pattern.
 */

const CLOUD = 'https://www.octobot.cloud';

const STRATEGIES: Feature[] = [
  {
    icon: '🧠',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.ai.title',
      message: 'AI trading',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.ai.description',
      message: 'Let an AI strategy adapt your trades to market conditions.',
      description: 'Strategy card description',
    }),
  },
  {
    icon: '📊',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.dca.title',
      message: 'DCA',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.dca.description',
      message: 'Dollar-cost average into the asset on a fixed schedule.',
      description: 'Strategy card description',
    }),
  },
  {
    icon: '▦',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.grid.title',
      message: 'Grid trading',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.grid.description',
      message:
        'Capture range-bound volatility with layered buy and sell orders.',
      description: 'Strategy card description',
    }),
  },
  {
    icon: '🧺',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.baskets.title',
      message: 'Crypto baskets',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.baskets.description',
      message: 'Hold the coin as part of a diversified, themed basket.',
      description: 'Strategy card description',
    }),
  },
  {
    icon: '📈',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.tradingview.title',
      message: 'TradingView',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.tradingview.description',
      message: 'Automate any TradingView strategy or indicator alert.',
      description: 'Strategy card description',
    }),
  },
  {
    icon: '⚙️',
    title: translate({
      id: 'programmatic.coinTradingBot.strategy.custom.title',
      message: 'Custom strategies',
      description: 'Strategy card title',
    }),
    description: translate({
      id: 'programmatic.coinTradingBot.strategy.custom.description',
      message: 'Build, backtest and optimize your own trading logic.',
      description: 'Strategy card description',
    }),
  },
];

interface CoinTradingBotData {
  crypto: Cryptocurrency;
}

export default function CoinTradingBot({
  data,
}: {
  data: CoinTradingBotData;
}): ReactNode {
  const {crypto} = data;

  // Prefer the coin's own FAQ entries; fall back to a generic set so the
  // page always has an FAQ section.
  const faqItems: FaqJsonLdItem[] =
    crypto.faq && crypto.faq.length > 0
      ? crypto.faq.map((entry) => ({
          question: entry.question,
          answer: entry.answer,
        }))
      : [
          {
            question: translate(
              {
                id: 'programmatic.coinTradingBot.faq.how.question',
                message: 'How does a {name} trading bot work?',
                description: 'FAQ question; {name} is the coin name',
              },
              {name: crypto.name},
            ),
            answer: translate(
              {
                id: 'programmatic.coinTradingBot.faq.how.answer',
                message:
                  'A {name} trading bot runs a strategy you choose against your own exchange account, placing {symbol} orders automatically as the strategy signals them.',
                description: 'FAQ answer; {name} is the coin name, {symbol} the ticker',
              },
              {name: crypto.name, symbol: crypto.symbol},
            ),
          },
          {
            question: translate(
              {
                id: 'programmatic.coinTradingBot.faq.free.question',
                message: 'Is the {name} trading bot free?',
                description: 'FAQ question; {name} is the coin name',
              },
              {name: crypto.name},
            ),
            answer: translate({
              id: 'programmatic.coinTradingBot.faq.free.answer',
              message:
                'OctoBot is open source and free to self-host. You can also start on OctoBot App — some advanced strategies and baskets need a paid plan.',
              description: 'FAQ answer',
            }),
          },
          {
            question: translate(
              {
                id: 'programmatic.coinTradingBot.faq.custody.question',
                message: 'Who holds my {symbol}?',
                description: 'FAQ question; {symbol} is the ticker',
              },
              {symbol: crypto.symbol},
            ),
            answer: translate({
              id: 'programmatic.coinTradingBot.faq.custody.answer',
              message:
                'You do. OctoBot connects to your exchange through an API key and never takes custody of your funds.',
              description: 'FAQ answer',
            }),
          },
        ];

  const title = translate(
    {
      id: 'programmatic.coinTradingBot.layout.title',
      message: '{name} trading bot',
      description: 'Page title; {name} is the coin name',
    },
    {name: crypto.name},
  );

  return (
    <LandingLayout
      title={title}
      description={translate(
        {
          id: 'programmatic.coinTradingBot.layout.description',
          message:
            'Automate your {name} ({symbol}) trading with OctoBot — AI strategies, DCA, grid trading or TradingView signals, on your own exchange account.',
          description:
            'Page meta description; {name} is the coin name, {symbol} the ticker',
        },
        {name: crypto.name, symbol: crypto.symbol},
      )}>
      <FaqJsonLd items={faqItems} />
      <BreadcrumbsJsonLd
        trail={[{name: title, path: `/${crypto.slug}-trading-bot`}]}
      />
      <div className={shared.gridVeil} aria-hidden="true" />

      <Hero
        eyebrow={translate(
          {
            id: 'programmatic.coinTradingBot.hero.eyebrow',
            message: '{name} trading bot',
            description: 'Hero eyebrow; {name} is the coin name',
          },
          {name: crypto.name},
        )}
        title={
          <Translate
            id="programmatic.coinTradingBot.hero.title"
            description="Hero title; {name} is a styled span with the coin name"
            values={{
              name: <span className="ng-text-gradient">{crypto.name}</span>,
            }}>
            {'Automate your {name} trading'}
          </Translate>
        }
        subtitle={translate(
          {
            id: 'programmatic.coinTradingBot.hero.subtitle',
            message:
              'Run an automated strategy on {name} ({symbol}) — pick a ready-made strategy or build your own, backtest it, and let OctoBot trade it around the clock.',
            description:
              'Hero subtitle; {name} is the coin name, {symbol} the ticker',
          },
          {name: crypto.name, symbol: crypto.symbol},
        )}
        actions={[
          {
            label: translate(
              {
                id: 'programmatic.coinTradingBot.hero.action.start',
                message: 'Automate {symbol}',
                description: 'Hero CTA label; {symbol} is the ticker',
              },
              {symbol: crypto.symbol},
            ),
            to: CLOUD,
          },
          {
            label: translate({
              id: 'programmatic.coinTradingBot.hero.action.guides',
              message: 'Read the guides',
              description: 'Hero secondary CTA label',
            }),
            to: '/guides/octobot',
            variant: 'ghost',
          },
        ]}
        meta={[
          {label: crypto.symbol, dot: true},
          {
            label: translate({
              id: 'programmatic.coinTradingBot.hero.meta.openSource',
              message: 'Open source',
              description: 'Hero meta label',
            }),
          },
          {
            label: translate({
              id: 'programmatic.coinTradingBot.hero.meta.selfCustody',
              message: 'Self-custody',
              description: 'Hero meta label',
            }),
          },
        ]}
      />

      <Section
        eyebrow={translate({
          id: 'programmatic.coinTradingBot.strategies.eyebrow',
          message: 'Strategies',
          description: 'Section eyebrow',
        })}
        title={translate(
          {
            id: 'programmatic.coinTradingBot.strategies.title',
            message: 'Ways to trade {name} automatically',
            description: 'Section title; {name} is the coin name',
          },
          {name: crypto.name},
        )}
        lead={translate(
          {
            id: 'programmatic.coinTradingBot.strategies.lead',
            message:
              'Every strategy runs {symbol} orders on your own connected exchange account.',
            description: 'Section lead; {symbol} is the ticker',
          },
          {symbol: crypto.symbol},
        )}>
        <FeatureGrid features={STRATEGIES} columns={3} />
      </Section>

      <Section
        align="left"
        eyebrow={translate({
          id: 'programmatic.coinTradingBot.about.eyebrow',
          message: 'About the asset',
          description: 'Section eyebrow',
        })}
        title={translate(
          {
            id: 'programmatic.coinTradingBot.about.title',
            message: 'What is {name}?',
            description: 'Section title; {name} is the coin name',
          },
          {name: crypto.name},
        )}
        lead={translate({
          id: 'programmatic.coinTradingBot.about.lead',
          message:
            'A quick primer on the asset before you point a bot at it.',
          description: 'Section lead',
        })}>
        <GlassCard variant="strong" padded className={shared.panel}>
          <p className={shared.prose}>{crypto.whatIs}</p>
        </GlassCard>
      </Section>

      <Section
        eyebrow={translate({
          id: 'programmatic.coinTradingBot.price.eyebrow',
          message: 'Market',
          description: 'Section eyebrow',
        })}
        title={translate(
          {
            id: 'programmatic.coinTradingBot.price.title',
            message: '{name} live market',
            description: 'Section title; {name} is the coin name',
          },
          {name: crypto.name},
        )}
        lead={translate(
          {
            id: 'programmatic.coinTradingBot.price.lead',
            message: 'The {symbol}/USDT market your bot would trade.',
            description: 'Section lead; {symbol} is the ticker',
          },
          {symbol: crypto.symbol},
        )}>
        <div className={shared.chart}>
          <TradingViewWidget symbol={`BINANCE:${crypto.symbol}USDT`} />
        </div>
      </Section>

      <Section
        eyebrow={translate({
          id: 'programmatic.coinTradingBot.faq.eyebrow',
          message: 'FAQ',
          description: 'Section eyebrow',
        })}
        title={translate(
          {
            id: 'programmatic.coinTradingBot.faq.title',
            message: '{name} trading bot FAQ',
            description: 'Section title; {name} is the coin name',
          },
          {name: crypto.name},
        )}>
        <FAQ items={faqItems} />
      </Section>

      <CTABand
        title={
          <Translate
            id="programmatic.coinTradingBot.cta.title"
            description="CTA band title; {name} is the coin name, {autopilot} a styled span"
            values={{
              name: crypto.name,
              autopilot: (
                <span className="ng-text-frost">
                  <Translate
                    id="programmatic.coinTradingBot.cta.titleAutopilot"
                    description="CTA band title accent">
                    on autopilot.
                  </Translate>
                </span>
              ),
            }}>
            {'Your {name} strategy, {autopilot}'}
          </Translate>
        }
        description={translate(
          {
            id: 'programmatic.coinTradingBot.cta.description',
            message:
              'Create a free OctoBot, connect your exchange and automate {name} today.',
            description: 'CTA band description; {name} is the coin name',
          },
          {name: crypto.name},
        )}
        actions={[
          {
            label: translate({
              id: 'programmatic.coinTradingBot.cta.action.start',
              message: 'Get started',
              description: 'CTA band label',
            }),
            to: CLOUD,
          },
          {
            label: translate(
              {
                id: 'programmatic.coinTradingBot.cta.action.dca',
                message: '{symbol} DCA bot',
                description: 'CTA band secondary label; {symbol} is the ticker',
              },
              {symbol: crypto.symbol},
            ),
            to: `/${crypto.slug}-dca-bot`,
            variant: 'ghost',
          },
        ]}
      />
    </LandingLayout>
  );
}
